import type { Env as WorkerEnv } from './index';

// `cloudflare:test`'s `env` (see @cloudflare/vitest-pool-workers/types) is
// typed as `Cloudflare.Env`, an empty interface meant to be augmented by
// declaration merging — normally generated by `wrangler types`. This project
// doesn't run that step, so merge our own `Env` (worker/index.ts) in by hand.
declare global {
  namespace Cloudflare {
    interface Env extends WorkerEnv {}
  }
}

export {};
